// Upgrade suite (PROP-0003 M6c, REQ-HOST-2, INV-14): every seeded store fixture (generated by
// `pnpm gen:upgrade-fixture <label>` from a release's code, never edited) is migrated to the
// current code by booting the shipped profile on it through the real dsh launcher. Old runs must
// still answer `explain` and `result` as they did, and every record must validate.
import { type ChildProcess, execFileSync, spawn } from 'node:child_process'
import { existsSync, mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { DatabaseSync } from 'node:sqlite'
import { fileURLToPath } from 'node:url'
import { setTimeout as sleep } from 'node:timers/promises'
import { Client } from '@modelcontextprotocol/sdk/client/index.js'
import { StreamableHTTPClientTransport } from '@modelcontextprotocol/sdk/client/streamableHttp.js'
import type { Transport } from '@modelcontextprotocol/sdk/shared/transport.js'
import { SchemaRegistry } from '@tsuuanmi/system-libs'
import { afterEach, describe, expect, it } from 'vitest'
import type { Manifest } from './generate.ts'

const bin = fileURLToPath(new URL('../../lib/bin.js', import.meta.url))
const FIXTURES = fileURLToPath(new URL('./fixtures', import.meta.url))
const labels = readdirSync(FIXTURES, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name).sort()

let child: ChildProcess | undefined
const homes: string[] = []
afterEach(() => {
  // Kill the whole group: a killed wrapper alone would orphan the dsh child and its port.
  if (child?.pid !== undefined && child.exitCode === null) {
    try {
      process.kill(-child.pid, 'SIGKILL')
    } catch {
      // the group already exited
    }
  }
  child = undefined
  for (const home of homes.splice(0)) rmSync(home, { recursive: true, force: true })
})

async function waitFor(path: string, timeoutMs: number): Promise<void> {
  for (const deadline = Date.now() + timeoutMs; !existsSync(path);) {
    if (Date.now() > deadline) throw new Error(`timed out waiting for ${path}`)
    await sleep(200)
  }
}

describe('upgrade: seeded store fixtures migrate to the current code (INV-14)', () => {
  it('has at least one fixture', () => {
    expect(labels.length).toBeGreaterThan(0)
  })

  for (const label of labels) {
    it(`boots ${label}: every old run still explains and answers as it did, and every record validates`, async () => {
      const fixture = join(FIXTURES, label)
      const manifest = JSON.parse(readFileSync(join(fixture, 'manifest.json'), 'utf8')) as Manifest
      const home = mkdtempSync(join(tmpdir(), 'system-upgrade-'))
      homes.push(home)
      const env = { ...process.env, DSH_HOME: home }
      execFileSync(process.execPath, [bin, 'init'], { env, stdio: 'pipe' })
      const store = join(home, 'system', 'system.db')
      rmSync(store, { force: true })
      const seeded = new DatabaseSync(store)
      seeded.exec(readFileSync(join(fixture, 'system.sql'), 'utf8'))
      const before = new Map((seeded.prepare('SELECT owner, MAX(version) AS version FROM system_migrations GROUP BY owner').all() as Array<{ owner: string; version: number }>).map((m) => [m.owner, m.version]))
      seeded.close()

      writeFileSync(join(home, 'port0.yml'), '- id: webserver\n  config:\n    host: 127.0.0.1\n    port: 0\n')
      child = spawn(process.execPath, [bin, 'start', '--patch', join(home, 'port0.yml')], { env, stdio: 'pipe', detached: true })
      const discoveryPath = join(home, 'system', 'mcp.json')
      await waitFor(discoveryPath, 90_000)
      const { url, tokenFiles } = JSON.parse(readFileSync(discoveryPath, 'utf8')) as { url: string; tokenFiles: { operator: string } }
      const client = new Client({ name: 'upgrade', version: '0' })
      await client.connect(new StreamableHTTPClientTransport(new URL(url), { requestInit: { headers: { authorization: `Bearer ${readFileSync(tokenFiles.operator).toString('base64url')}` } } }) as unknown as Transport)
      try {
        for (const run of manifest.runs) {
          const explained = await client.callTool({ name: 'explain', arguments: { id: run.runId } })
          expect(explained.isError, `${label} explain ${run.runId}`).not.toBe(true)
          expect(explained.structuredContent, `${label} explain ${run.runId}`).toMatchObject({ runId: run.runId, template: run.template, status: run.status })
          expect((explained.structuredContent as { nodes: unknown[] }).nodes).toHaveLength(run.nodes)
          const result = await client.callTool({ name: 'result', arguments: { runId: run.runId, waitSeconds: 0 } })
          expect(result.structuredContent, `${label} result ${run.runId}`).toMatchObject({ runId: run.runId, status: run.status })
        }
      } finally {
        await client.close()
      }
      const exited = new Promise((resolve) => child?.on('exit', resolve))
      child.kill('SIGTERM')
      await exited

      // After the upgrade: no migration went backwards, and every record validates against its schema.
      const db = new DatabaseSync(store, { readOnly: true })
      try {
        for (const { owner, version } of db.prepare('SELECT owner, MAX(version) AS version FROM system_migrations GROUP BY owner').all() as Array<{ owner: string; version: number }>) {
          expect(version, `migrations of ${owner}`).toBeGreaterThanOrEqual(before.get(owner) ?? 0)
        }
        const schemas = new SchemaRegistry()
        const records = [
          ...(db.prepare('SELECT record FROM workflow_nodes').all() as Array<{ record: string }>).map((r) => r.record),
          ...(db.prepare('SELECT record FROM worker_sessions').all() as Array<{ record: string }>).map((r) => r.record),
        ]
        for (const record of records) schemas.assertRecord(JSON.parse(record) as { schema?: unknown })
        for (const { envelope } of db.prepare('SELECT envelope FROM artifacts').all() as Array<{ envelope: string }>) {
          const parsed = JSON.parse(envelope) as { schema?: unknown; bodySchema: string; body: unknown }
          schemas.assertRecord(parsed)
          schemas.assert(parsed.bodySchema, parsed.body)
        }
        expect(records.length).toBeGreaterThan(0)
      } finally {
        db.close()
      }
    }, 180_000)
  }
})
